async function processMessage(message) {
  try {
    await handleOrder(message.body);
    await channel.ack(message);
  } catch (error) {
    if (isTransient(error)) {
      console.warn('Transient error, will retry:', error.message);
      await channel.nack(message, false, true); // requeue for retry
    } else {
      console.error('Permanent error, sending to DLQ:', error.message);
      await channel.nack(message, false, false); // drop to DLQ
    }
  }
}

function isTransient(error) {
  const transientCodes = [408, 429, 500, 502, 503, 504];
  return transientCodes.includes(error.statusCode) || error.code === 'ETIMEDOUT';
}

async Task ProcessMessageAsync(Message message, CancellationToken ct)
{
    try
    {
        await _orderService.ProcessAsync(message.Body, ct);
        await _channel.BasicAckAsync(message.DeliveryTag, multiple: false, ct);
    }
    catch (Exception ex)
    {
        if (IsTransient(ex))
        {
            _logger.LogWarning(ex, "Transient failure, requeuing message {Id}", message.MessageId);
            await _channel.BasicNackAsync(message.DeliveryTag, multiple: false, requeue: true, ct);
        }
        else
        {
            _logger.LogError(ex, "Permanent failure, dead-lettering message {Id}", message.MessageId);
            await _channel.BasicNackAsync(message.DeliveryTag, multiple: false, requeue: false, ct);
        }
    }
}

static bool IsTransient(Exception ex) =>
    ex is TimeoutException
    || ex is HttpRequestException
    || ex is TransientDatabaseException;

class TransientDatabaseException : Exception { }
